SELECT json_object('obs','bytes','declined',CASE WHEN (SELECT payload FROM source_blob WHERE doc_id=1) IS NULL THEN 1 ELSE 0 END,'value_kind','bytes','value_hex',(SELECT hex(substr(payload,1,64)) FROM source_blob WHERE doc_id=1),'coord',json_object('format',(SELECT format FROM documents WHERE doc_id=1),'kind','byte-range','ordinal','0:64'),'provenance',json_object('class','verbatim','span',json_array(0,64)),'exact',json_object('length',(SELECT source_len FROM documents WHERE doc_id=1),'sha256',(SELECT source_sha256 FROM documents WHERE doc_id=1)),'revision',json_object('family_id',(SELECT family_id FROM revisions WHERE doc_id=1),'member_id',(SELECT member_id FROM revisions WHERE doc_id=1),'is_head',(SELECT is_head FROM revisions WHERE doc_id=1)))